export function setting(key) {
  return BY_KEY.get(key)
}

const DURATION = /^([0-9]+)(ms|s|m|h)$/
const DURATION_MS = { ms: 1n, s: 1000n, m: 60000n, h: 3600000n }

/**
 * Coerce raw text into a setting's declared type, rendered the way the type prints it.
 * @param {{key: string, type: string, members?: string[]}} declared - the setting.
 * @param {string} text - the raw text a layer wrote, or the schema default.
 * @returns {string} the rendered value.
 * @throws {Error} `<key> is not a <type>: <text>` (or the list and enum wordings) when it does not fit.
 */
export function coerce(declared, text) {
  switch (declared.type) {
    case 'string':
      return text
    case 'integer':
      if (!/^-?(0|[1-9][0-9]*)$/.test(text)) throw new Error(`${declared.key} is not an integer: ${text}`)
      return text
    case 'boolean':
      if (text !== 'true' && text !== 'false') throw new Error(`${declared.key} is not a boolean: ${text}`)
      return text
    case 'enum':
      if (!declared.members.includes(text)) {
        throw new Error(`${declared.key} is not one of ${declared.members.join('|')}: ${text}`)
      }
      return text
    case 'duration': {
      const match = DURATION.exec(text)
      if (!match) throw new Error(`${declared.key} is not a duration: ${text}`)
      return (BigInt(match[1]) * DURATION_MS[match[2]]).toString()
    }
    case 'list': {
      if (text === '') return ''
      const seen = new Set()
      const items = []
      for (const raw of text.split(',')) {
        const item = raw.trim()
        if (item === '') throw new Error(`${declared.key} has an empty item: ${text}`)
        if (!seen.has(item)) {
          seen.add(item)
          items.push(item)
        }
      }
      return items.join(',')
    }
    default:
      throw new Error(`unknown type ${declared.type}`)
  }
}"}

