import { IniError, indent, valueAt } from './ini.js'
import { setting } from './schema.js'

/**
 * Merge named layers, later over earlier.
 * @param {readonly {name: string, values: Map<string, {text: string, line: number, column: number}>}[]} layers
 *   - the layers, weakest first.
 * @returns {Map<string, {layer: string, text: string, line: number, column: number}>} each key's
 *   winning entry, naming the layer that set it.
 */
export function merge(layers) {
  const merged = new Map()
  for (const layer of layers) {
    for (const [key, entry] of layer.values) merged.set(key, { layer: layer.name, ...entry })
  }
  return merged
}

const ENV_NAME = key => `CONF_${key.toUpperCase().replace(/\./g, '_')}`

/**
 * Parse an environment layer: a line per variable, `CONF_`-prefixed names naming schema keys.
 * @param {string} text - the whole of standard input.
 * @returns {Map<string, {text: string, line: number, column: number}>} each schema key's raw
 *   value, its line, and the column of its position.
 * @throws {IniError} on the first line the grammar refuses, an unknown or repeated name.
 */
export function parseEnv(text) {
  const byName = new Map()
  for (const declared of require('./schema.js').SETTINGS) byName.set(ENV_NAME(declared.key), declared.key)
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  const values = new Map()
  const seen = new Set()
  for (const [index, raw] of lines.entries()) {
    const line = index + 1
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const column = indent(raw)
    const split = trimmed.indexOf('=')
    if (split === -1) throw new IniError(line, column, 'expected NAME=VALUE')
    const name = trimmed.slice(0, split).trim()
    if (name === '') throw new IniError(line, column, 'expected a variable name')
    const key = byName.get(name)
    if (key === undefined) throw new IniError(line, column, `unknown environment variable ${name}`)
    if (seen.has(name)) throw new IniError(line, column, `${name} is set twice`)
    seen.add(name)
    const { text: value, column: valueColumn } = valueAt(raw, trimmed, split)
    values.set(key, { text: value, line, column: valueColumn })
  }
  return values
}
"}

