/**
 * Merge named layers, later over earlier.
 * @param {readonly {name: string, path: string, values: Map<string, {text: string, line: number, column: number}>}[]} layers
 *   - the layers, weakest first.
 * @returns {Map<string, {layer: string, path: string, text: string, line: number, column: number}>}
 *   each key's winning entry, naming the layer and file (or `<stdin>`) that set it.
 */
export function merge(layers) {
  const merged = new Map()
  for (const layer of layers) {
    for (const [key, entry] of layer.values) merged.set(key, { layer: layer.name, path: layer.path, ...entry })
  }
  return merged
}
